function RHO_COEFFS(prec, M):
    acc <- zero vector of length prec
    for m in 0 .. M-1:
        P <- mono(0)                       # the constant series 1
        for j in 0 .. m:
            block <- 1 + q^{2j+1} + q^{4j+2}
            P <- TRUNC_MUL(P, block)        # Cauchy product mod q^prec
        Pinv <- INVERT(P)                   # b0=1; bi = -sum ak b(i-k)
        term <- TRUNC_MUL(mono(2*m*(m+1)), Pinv)
        acc  <- acc + term                  # entrywise
    return acc                              # acc[n] = r(n) for n < prec

# Correctness: term m has order 2m(m+1); choose M with 2M(M+1) >= prec
# so all dropped terms vanish below the window.

function CHECK_CYCLOTOMIC(prec, kmax):
    for k in 0 .. kmax with 3k < prec:
        lhs <- TRUNC_MUL(1 + x^k + x^{2k}, 1 - x^k)
        rhs <- 1 - x^{3k}
        assert lhs == rhs
    # reciprocal pattern: 1/(1 + x + x^2) = sum_t (x^{3t} - x^{3t+1})

